export default async function install(app) {
  let disposed=false,timer=0,releaseWait=null,frame=0;
  const inset=Number(app.config.insetPx??8);
  app.onCleanup(()=>{disposed=true;if(timer)clearTimeout(timer);releaseWait?.();});
  const resolve=()=>{const host=document.getElementById('app-widget-host-place-search'),search=document.getElementById('app-widget-place-search'),panel=document.querySelector('section[aria-label="Thema\'s"]'),root=search?.shadowRoot,auto=root?.querySelector('calcite-autocomplete'),field=auto?.shadowRoot?.querySelector('calcite-input'),input=field?.shadowRoot?.querySelector('input');return{host,search,panel,root,auto,field,input};};
  const started=performance.now();let ready=resolve();while(!disposed&&!(ready.host?.shadowRoot&&ready.panel?.firstElementChild&&ready.input)&&performance.now()-started<15000){await new Promise(done=>{releaseWait=done;timer=setTimeout(()=>{timer=0;releaseWait=null;done();},50);});ready=resolve();}
  app.assert(!disposed,'Search style installation cancelled');app.assert(ready.host?.shadowRoot&&ready.panel?.firstElementChild&&ready.input,'Search input did not finish rendering within 15 seconds');
  const {host,search,panel}=ready,header=panel.firstElementChild,view=app.view.container;host.expanded=true;
  const outer=document.createElement('style');outer.textContent='#app-widget-host-place-search,#app-widget-place-search{width:var(--prowise-search-width)!important;height:var(--prowise-search-height)!important;max-width:var(--prowise-search-max-width)!important;box-sizing:border-box!important;background:#fff!important;border-radius:20px!important;overflow:hidden!important;font-family:Poppins,sans-serif!important;--calcite-color-foreground-1:#fff;--calcite-color-foreground-2:#fff;--calcite-color-foreground-3:#fff;--calcite-font-family:Poppins,sans-serif}#app-widget-host-place-search::part(content){background:#fff!important;border-radius:20px!important;overflow:hidden!important}';document.head.append(outer);
  const inserted=[];const apply=()=>{const root=search.shadowRoot,auto=root?.querySelector('calcite-autocomplete'),field=auto?.shadowRoot?.querySelector('calcite-input');for(const[sr,css]of[[root,':host,:host > div,:host > div:first-child{background:#fff!important;border-radius:20px!important;overflow:hidden!important;box-shadow:none!important;box-sizing:border-box!important;height:100%!important}'],[auto?.shadowRoot,':host{background:#fff!important;height:100%!important}'],[field?.shadowRoot,':host{background:#fff!important;border:0!important;box-shadow:none!important;height:100%!important}input,[part="input"],.input{background:#fff!important;border:0!important;box-shadow:none!important;font-family:Poppins,sans-serif!important;height:100%!important}']]){if(!sr||inserted.some(s=>s.parentNode===sr))continue;const s=document.createElement('style');s.textContent=css;sr.append(s);inserted.push(s);}};
  function align(){frame=0;if(disposed||!host.isConnected||!header.isConnected)return;const v=view.getBoundingClientRect(),p=panel.getBoundingClientRect(),h=header.getBoundingClientRect();if(!v.width||!h.height)return;const leftInset=p.left-v.left,room=v.right-leftInset-p.right-16,outerWidth=Math.min(460,room),width=Math.max(80,outerWidth-inset*2),hostHeight=Math.max(32,h.height-inset*2);for(const el of[host,search]){el.style.setProperty('--prowise-search-width',width+'px');el.style.setProperty('--prowise-search-height',hostHeight+'px');el.style.setProperty('--prowise-search-max-width',`calc(100vw - ${32+inset*2}px)`);el.style.removeProperty('top');el.style.position='';el.style.transform='none';}
    const hostBox=host.getBoundingClientRect();host.style.transform=`translate(${v.right-leftInset-(outerWidth+hostBox.width)/2-hostBox.left}px,${h.top+(h.height-hostBox.height)/2-hostBox.top}px)`;
    const searchBox=search.getBoundingClientRect();const targetX=v.right-leftInset-(outerWidth+searchBox.width)/2;const targetY=h.top+(h.height-searchBox.height)/2;
    search.style.transform=`translate(${targetX-searchBox.left}px,${targetY-searchBox.top}px)`;apply();}
  const schedule=()=>{if(!disposed&&!frame)frame=requestAnimationFrame(align);};const observer=new ResizeObserver(schedule);observer.observe(view);observer.observe(panel);observer.observe(header);window.addEventListener('resize',schedule);
  const inspect=()=>{const r=search.getBoundingClientRect(),h=header.getBoundingClientRect(),hostBox=host.getBoundingClientRect(),bar=search.shadowRoot?.querySelector('div'),b=bar?.getBoundingClientRect();return{insetPx:inset,host:{height:hostBox.height,topInset:hostBox.top-h.top,bottomInset:h.bottom-hostBox.bottom},search:{width:r.width,height:r.height,topInset:r.top-h.top,bottomInset:h.bottom-r.bottom,background:getComputedStyle(search).backgroundColor},innerBackground:b?getComputedStyle(bar).backgroundColor:null};};app.actions.register('inspect-search-bar',inspect);
  app.onCleanup(()=>{if(frame)cancelAnimationFrame(frame);observer.disconnect();window.removeEventListener('resize',schedule);outer.remove();inserted.forEach(s=>s.remove());for(const el of[host,search]){el.style.removeProperty('--prowise-search-width');el.style.removeProperty('--prowise-search-height');el.style.removeProperty('--prowise-search-max-width');el.style.transform='';}});align();apply();return inspect();
}